let settings,commonBackground,backgrounds,favorites,visits;
function loadUser(){try{settings=validateProfile(usRead('profile',defaults));}catch{settings=structuredClone(defaults);}
 if(!usRead('profile',null)&&matchMedia('(prefers-reduced-motion: reduce)').matches)settings.reduced=true;
 try{const raw=usRead('common-bg',{background:'none',base:'black',opacity:25}),b=validateProfile({...defaults,...raw});commonBackground={background:b.background,base:b.base,opacity:b.opacity};}catch{commonBackground={background:'none',base:'black',opacity:25};}
 backgrounds=usRead('backgrounds',{});if(!backgrounds||typeof backgrounds!=='object'||Array.isArray(backgrounds))backgrounds={};
 favorites=usRead('favorites',[]);if(!Array.isArray(favorites))favorites=[];
 visits=usRead('visits',{});if(!visits||typeof visits!=='object'||Array.isArray(visits))visits={};}
loadUser();
