const SCENE_DECOR=Object.freeze(Object.fromEntries(['jelly','jungle','savanna','well','giants','castells','balloons','magician','door','fira','waiter','lighthouse','robotbuild','flora','frog','viatge','daynight','constellations','orchestra','wind','piro',...SCAN_ACTIVITIES.map(x=>x.id)].map(id=>[id,Object.freeze({background:'full'})])));
