 if(src){const im=new Image();im.onload=()=>{if(!canvas.isConnected)return;const k=Math.max(w/im.width,h/im.height);c.drawImage(im,(w-im.width*k)/2,(h-im.height*k)/2,im.width*k,im.height*k);};im.src=src;return;}
