 if(audio&&master){const t=audio.currentTime,g=settings.volume/100*.35;try{master.gain.cancelScheduledValues(t);master.gain.setValueAtTime(0,t);master.gain.linearRampToValueAtTime(g,t+.4);}catch{master.gain.value=g;}}
