function switchButtons(item){const i=settings.swap?1:0,j=1-i;return settings.mode===2&&item.type==='scan'?`<button class="switch-button secondary" data-switch="${i}">Avança <span class="keycap">${(settings.source==='keyboard'?keyName(settings.keys[i]):'Commutador '+(i+1))}</span></button><button class="switch-button" data-switch="${j}">Tria <span class="keycap">${(settings.source==='keyboard'?keyName(settings.keys[j]):'Commutador '+(j+1))}</span></button>`:`<button class="switch-button" data-switch="0">${item.type==='ce'?'Pim!':'Tria'} <span class="keycap">${settings.source==='keyboard'?keyName(settings.keys[0]):'Commutador 1'}</span></button>`;}
// ---------- The scanning boards of 0.16 (On anem? and Detectius de sons) ----------
// The scene fills the stage and the options are zones of it (tauler.js): each zone has a transparent button over it (for the mouse, the
// touch screen and the assistive technologies); the commands go in the strip at the bottom, at the left, and the switch hint in its centre.
// The review tools (tools/tauler-review.mjs) can ask for the list of every sound the app starts or stops, to render the sound of a video
