 const zone=(x,i)=>{const z=zones[i];return z?`<button class="board-zone ${scan.index===i?'scanned':''}" data-choice="${i}" aria-current="${scan.index===i}" aria-label="${escape(x.label)}" style="left:${z.x.toFixed(1)}px;top:${z.y.toFixed(1)}px;width:${z.w.toFixed(1)}px;height:${z.h.toFixed(1)}px${z.kind==='poly'&&z.pts?`;clip-path:polygon(${z.pts.map(p=>`${(p[0]-z.x).toFixed(1)}px ${(p[1]-z.y).toFixed(1)}px`).join(',')});border-radius:0`:''}"></button>`:'';};
