function exSettings(){const sel=(k,label,opts,hint)=>`<div class="field"><label for="${k}">${label}</label><select id="${k}" data-string="${k}">${opts.map(([v,l])=>`<option value="${v}" ${settings[k]===v?'selected':''}>${l}</option>`).join('')}</select>${hint?`<span class="hint">${hint}</span>`:''}</div>`;
 return `<div class="form-grid">${sel('exMode','Mode',[['encaixa','Encaixa: un forat marcat, només hi entra la seva peça'],['lliure','Lliure: cap forat marcat, cada peça va al seu forat']],'Encaixa és aparellar amb una mostra: el forat il·luminat. Lliure no té tries dolentes, per a qui encara aprèn l’encercament.')}${sel('exHint','Pista al forat',[['imatge','Imatge: el dibuix de la figura, suau, dins del forat'],['silueta','Silueta: només la forma del forat']])}${sel('exLike','Semblança de les peces',[['diferents','Diferents: peces de formes diferents de la que hi va'],['semblants','Semblants: peces de forma semblant (dues figures dretes, dues d’amples…)']])}${sel('exHelp','Ajuda després de',[['mai','Mai'],['2','2 peces que no hi van'],['3','3 peces que no hi van']],'La peça que hi va es balanceja suaument a la safata fins que es posa.')}${sel('exPace','Ritme',[['normal','Normal'],['calmat','Calmat: tot un 28 % més a poc a poc (el vol, les històries, la festa i la música)']])}</div>${checkbox('exGlow','Llum al forat marcat','El forat de la ronda s’il·lumina amb una llum càlida que respira a poc a poc. Sense la llum, el forat es distingeix només per la pista.')}`;}
// Fem castells, 0.45.6: the colour of the colla's shirt, as swatches only (no names on screen; the names are for screen readers).
// The first swatch, a wheel of the round colours, keeps the colour that changes with every round.
const FEM_SHIRT_NAMES=Object.freeze({vermell:'Vermell',rosat:'Rosat',granat:'Granat',magenta:'Magenta',malva:'Malva',morat:'Morat',cel:'Blau cel',blau:'Blau',mari:'Blau marí',turquesa:'Turquesa',verd:'Verd',llima:'Verd llima',groc:'Groc',taronja:'Taronja',marro:'Marró',gris:'Gris'});
function femSettings(){const b=(k,bg,name)=>`<button data-setting="femShirt" data-value="${k}" class="${settings.femShirt===k?'active':''}" aria-pressed="${settings.femShirt===k}" aria-label="${name}"><span class="swatch shirt" style="background:${bg}"></span></button>`;
 return `<div class="field"><label>Color de la camisa a Fem castells</label><div class="segmented swatches shirts" role="group" aria-label="Color de la camisa">${b('ronda',`conic-gradient(${FEM_SHIRTS.join(',')},${FEM_SHIRTS[0]})`,'Un color diferent a cada ronda')}${Object.entries(FEM_SHIRT_COLORS).map(([k,c])=>b(k,c,FEM_SHIRT_NAMES[k])).join('')}</div><span class="hint">Els colors són els de les camises de les colles castelleres. La primera mostra, la roda de colors, fa que cada ronda porti una camisa diferent, com fins ara; qualsevol altra mostra vesteix tota la colla d’aquell color en totes les rondes. La gent de la pinya que ve d’altres colles conserva els seus colors. Sense decorat sobre la base negra, els colors més foscos destaquen menys.</span></div>`;}
function ggSettings(){return `<div class="field"><label for="ggCamera">Moviment de càmera a Gegants del blau</label><select id="ggCamera" data-string="ggCamera">${[['full','Ple: travellings, zooms i seguiment dels animals'],['soft','Suau: la càmera es mou menys i més a poc a poc']].map(([v,l])=>`<option value="${v}" ${settings.ggCamera===v?'selected':''}>${l}</option>`).join('')}</select><span class="hint">Amb «Reducció de moviment», cada escena es veu quieta, al mig del gest de l’animal.</span></div>`;}
// ---------- 0.46 · The settings of each activity, only in the settings menu inside that activity (Marc, 6 November 2026) ----------
// They are kept in the profile of the user who is playing like every other setting; a setting that several activities share (the plain
// background, the line of the dancing drawings, how continuous effects answer, the wait of Toc, toc) appears in each of them and says so.
const PLAIN_IDS=['castells','destinations','sounds','inventions','sources','pinta'],DB_IDS=['drawings','toys','kitchen'],HINT_IDS=['sounds','sources'];
const interactionApplies=item=>!!item&&!item.persona&&(!!(causeDefinition(item.id)?.continuous||item.continuous)||!!causeDefinition(item.id)?.wind||item.id==='viatge'||item.id==='frog');
const holdOnly=id=>id==='viatge'||id==='frog'||!!causeDefinition(id)?.wind;
const actName=id=>catalog.find(g=>g.id===id)?.name||id;
function sharedNote(ids,id,extra=''){const others=ids.filter(x=>x!==id&&catalog.some(g=>g.id===x)).map(actName);if(!others.length&&!extra)return '';const list=others.length>1?others.slice(0,-1).join(', ')+' i '+others[others.length-1]:others[0]||'';return `<span class="hint shared">Aquest ajust és compartit amb ${list}${extra?(list?' i ':'')+extra:''}: si el canvieu aquí, també hi canvia.</span>`;}
function selField(key,label,list,hint='',attr='string'){return `<div class="field"><label for="${key}">${label}</label><select id="${key}" data-${attr}="${key}">${list.map(([v,l])=>`<option value="${v}" ${settings[key]===v?'selected':''}>${l}</option>`).join('')}</select>${hint?`<span class="hint">${hint}</span>`:''}</div>`;}
function farFields(){return `<div class="form-grid">${selField('farSpeed','Velocitat de la llum',[['slow','Lenta: 16 segons per anar i tornar'],['medium','Mitjana: 11 segons'],['fast','Ràpida: 7 segons']])}${selField('farWindow','Temps per encertar',[['wide','Llarg: 3 segons'],['medium','Mitjà: 1,8 segons'],['narrow','Curt: 1 segon']])}${selField('farBoats','Barques al mar',[[1,'Una barca'],[2,'Dues barques'],[3,'Tres barques']],'La barca s’il·lumina suaument durant el temps en què es pot encertar. La dificultat no canvia mai sola.','number')}</div>`;}
function tocFields(id){return `<div class="form-grid">${selField('tcWait','Espera abans que truquin',[['short','Curta: de 2 a 4 segons'],['medium','Mitjana: de 4 a 7 segons'],['long','Llarga: de 7 a 10 segons']])}${selField('tcLeave','Quan ningú no obre',[['never','El visitant espera fins que premis'],['long','Se’n va al cap de 10 segons'],['medium','Se’n va al cap de 6 segons'],['short','Se’n va al cap de 3 segons']],`Si se’n va, torna a trucar al cap d’una estona. Prémer abans que truquin no fa res.${id==='door'?' El nombre de visites és el de «Passos de les construccions i històries», a la pestanya «L’experiència».':''}`)}</div>${sharedNote(['door'],id,'les activitats personalitzades «Qui s’amaga?»')}`;}
// Detectius de sons (0.48): how many instruments can appear, and whether the others on the stage may be of the same family.
function dsFields(){return `<div class="form-grid">${selField('dsPool','Instruments que poden sortir',[['8','8: arpa, violí, flauta, trompeta, marimba, glockenspiel, timbal i triangle'],['14','14: també piano, guitarra, violoncel, clarinet, trombó i pandereta'],['20','20: també contrabaix, oboè, fagot, trompa, tuba i gong']],'Cada instrument és el que es busca una vegada abans que cap altre torni a ser-ho. Quants n’hi ha a l’escenari ho diu «Opcions de contingut».')}${selField('dsFamily','Els altres instruments de l’escenari',[['altres','D’una altra família (més fàcil)'],['barreja','També de la mateixa família (més difícil)']],'Famílies: corda, vent de fusta, vent de metall, làmines i teclat, percussió.')}</div>`;}
function firaFields(){return `<div class="form-grid">${selField('fiRhythm','Ritme de les bombetes',[['lent','Lent: 1,6 segons per bombeta'],['normal','Normal: 1,1 segons'],['rapid','Ràpid: 0,8 segons']])}${selField('fiCalm','Calma abans de les bombetes',[['curta','Curta: d’1,5 a 2,5 segons'],['variable','Variable: d’1,5 a 4 segons'],['llarga','Llarga: de 3 a 6 segons']],'Cada vegada dura una estona diferent, perquè prémer seguint un ritme no funcioni.')}${selField('fiEarly','Si es prem abans de la tercera bombeta',[['res','No passa res'],['reinicia','Les bombetes s’apaguen i el compte torna a començar'],['lent','Surt igualment, però a poc a poc']])}${selField('fiPress','Quan no es prem després de la tercera',[['never','La figura espera fins que premis'],['long','Les bombetes s’apaguen al cap de 10 segons'],['medium','Al cap de 6 segons'],['short','Al cap de 3 segons']],'Si s’apaguen, el compte torna a començar al cap d’una estona.')}${selField('fiFirst','Primera atracció',[['bitlles','Les bitlles'],['cano','El canó de la bala humana'],['coet','El coet de corda'],['forca','La força'],['cavallets','La cursa de cavallets'],['atzar','A l’atzar']],'El nombre de llançaments abans del final és el de «Passos de les construccions i històries», a la pestanya «L’experiència». La dificultat no canvia mai sola.')}</div>`;}
function dbFields(id){return `<div class="form-grid">${selField('dbColor','Color de la línia',[['own','Els colors de cada dibuix'],['yellow','Groc'],['red','Vermell'],['white','Blanc (fosc sobre la base blanca)']])}${selField('dbSpeed','Velocitat',[['normal','Normal'],['slow','Lenta: el ball i la música, un 30 % més a poc a poc']],'S’aplica a partir de la pulsació següent.')}</div>${checkbox('dbStill','Sense desplaçament','El dibuix es queda quiet al seu lloc i només es mouen les seves parts: les rodes, els braços, les baquetes, les tapes.')}${sharedNote(DB_IDS,id)}`;}
function kaleidoFields(){return `${checkbox('kaleidoContrast','Contrast alt','Un sol color sobre negre i una forma gran i senzilla al centre (anells, pètals, un polígon, una estrella o punts), amb la mateixa música. El fons és sempre negre i llis.')}${selField('kaleidoColor','Color del contrast alt',[['yellow','Groc'],['white','Blanc'],['orange','Taronja'],['red','Vermell'],['pink','Rosa'],['green','Verd'],['blue','Blau']])}`;}
function plainField(id){const what={castells:'La plaça es mostra amb colors plans i menys detall.',destinations:'L’estació es mostra amb colors plans i cada porta mostra un símbol en lloc del paisatge.',sounds:'El templet es mostra amb colors plans i menys detall.',inventions:'La fàbrica es mostra amb colors plans i menys detall.',sources:'Els paisatges de paper conserven els colors i les vores, però sense les pinzellades.',pinta:'El paisatge es mostra amb menys detall.'}[id]||'';return checkbox('plainScene','Fons senzill',`${what} Hi ha menys detall per mirar i l’ordinador hi treballa menys.`)+sharedNote(PLAIN_IDS,id);}
function interactionField(id){const hold=holdOnly(id),others=catalog.filter(interactionApplies).map(g=>g.id);
 const list=hold?[['hold','Mentre es manté premut · acaba en deixar-lo anar'],['toggle','Una pulsació comença · la següent acaba']]:[['effect','Efecte complet per pulsació'],['hold','Mentre premo · acaba en alliberar'],['toggle','Una pulsació inicia · la següent atura']];
 const cur=hold?(settings.interaction==='toggle'?'toggle':'hold'):settings.interaction;
 return `<div class="field"><label for="interaction">Com respon al commutador</label><select id="interaction" data-string="interaction">${list.map(([v,l])=>`<option value="${v}" ${cur===v?'selected':''}>${l}</option>`).join('')}</select>${id==='wind'?'<span class="hint">El vent bufa mentre es manté premut; amb la segona opció, bufa fins a la pulsació següent.</span>':id==='frog'?'<span class="hint">La granota bufa mentre es manté premut i la bombolla vola en deixar-lo anar; amb la segona opció, una pulsació comença a bufar i la següent deixa anar la bombolla.</span>':id==='viatge'?'<span class="hint">El cremador s’encén mentre es manté premut; amb la segona opció, una pulsació l’encén i la següent l’apaga.</span>':''}</div>${sharedNote(others,id)}`;}
function activitySettings(item){if(!item)return '';const id=item.id,out=[];
 if(id==='lighthouse')out.push(farFields());if(id==='door'||item.persona&&item.tpl==='moment')out.push(tocFields(id));if(id==='fira')out.push(firaFields());if(id==='sounds')out.push(dsFields());if(DB_IDS.includes(id))out.push(dbFields(id));if(id==='kaleido')out.push(kaleidoFields());
 if(id==='castells')out.push(femSettings());if(id==='giants'&&!vdOn(id))out.push(ggSettings());if(LOAD_DIVES.includes(id)&&vdOn(id))out.push(`<div class="note">Les vint escenes es reprodueixen en vídeo (1080p), amb la seva música. Cada escena té la seva durada, sempre la mateixa: «Durada dels efectes» no s’hi aplica. Aquesta activitat es veu sempre amb el decorat complet.</div>`);if(id==='viatge')out.push(vgSettings());if(id==='encaix')out.push(exSettings());
 if(id==='daynight')out.push(`<div class="field"><label for="dayMoments">Moments del dia</label><select id="dayMoments" data-number="dayMoments">${[[8,'Vuit: de l’albada a la matinada'],[4,'Quatre: albada, migdia, posta i nit'],[2,'Dos: migdia i nit']].map(([n,l])=>`<option value="${n}" ${settings.dayMoments===n?'selected':''}>${l}</option>`).join('')}</select></div>`);
 if(id==='pot')out.push(selField('potPick','Ingredients',[['choose','L’infant els tria (tantes opcions com «Opcions de contingut»)'],['one','Un ingredient sorpresa a cada torn']],'Amb un ingredient sorpresa, la primera pulsació hi posa un ingredient màgic, la segona una galeta d’animal i la tercera, sobre el cullerot, fa que Glupòcrates la tasti.'));
 if(HINT_IDS.includes(id))out.push(checkbox('visualHint',id==='sounds'?'Pista visual al marc':'Pista visual al medalló',id==='sounds'?'Mostra dins del marc gran de dalt l’instrument que es busca. Si es desactiva, el marc només mostra ones i una nota.':'Mostra dins del medalló de dalt el paisatge d’on ve el so. Si es desactiva, el medalló només mostra ones.')+sharedNote(HINT_IDS,id));
 if(PLAIN_IDS.includes(id))out.push(plainField(id));if(interactionApplies(item))out.push(interactionField(id));return out.join('');}
function activityPanel(){const item=game?.item;return `<h3>${item?.name||''}</h3><p class="hint">Aquests ajustos només surten dins d’aquesta activitat. Es desen a ${usIsGuest()?'aquest dispositiu (convidat)':'l’usuari «'+escape(usName())+'»'}.</p>${activitySettings(item)}`;}
function userField(){return `<div class="field"><label>Qui juga</label><div class="user-line">${userBadge()}<strong>${escape(usName())}</strong>${page==='game'?'':'<button type="button" class="btn small" data-users>Usuaris…</button>'}</div><span class="hint">${usIsGuest()?'Com a convidat, els ajustos es desen en aquest dispositiu, sense registre.':'Els ajustos, els preferits, les activitats personalitzades i el registre es desen a aquest usuari, en aquest dispositiu.'}</span></div>`;}
function generalSettings(){return `<div class="form-grid">${userField()}<div class="field"><label>Com vols fer l’encercament?</label>${segmented('mode',[[1,'1 commutador'],[2,'2 commutadors']])}</div></div><div class="note">${settings.mode===1?'Amb un commutador, el marc recorre les opcions automàticament. Prem per triar l’opció ressaltada.':'Amb dos commutadors, el primer fa avançar el marc i el segon selecciona. El marc espera el teu gest.'}</div>${checkbox('swap','Intercanvia les funcions dels commutadors','En mode de dos commutadors: el primer tria i el segon avança.')} ${range('scanTime','Temps per opció ·',500,10000,100,' ms')}<div class="form-grid"><div class="field"><label for="duration">Durada dels efectes</label><select id="duration" data-number="duration">${[2,4,6,8,10,15].map(n=>`<option value="${n}" ${settings.duration===n?'selected':''}>${n} segons</option>`).join('')}</select></div><div class="field"><label for="steps">Passos de les construccions i històries</label><select id="steps" data-number="steps">${[3,5,7].map(n=>`<option value="${n}" ${settings.steps===n?'selected':''}>${n} pulsacions</option>`).join('')}</select><span class="hint">Fem castells en fa sempre 7, un pis per pulsació: pinya amb els baixos, segons, terços, quarts, dosos, aixecador i enxaneta.</span></div></div><div class="note">Els ajustos propis d’una activitat (per exemple, la llum d’El far, el color de la camisa de Fem castells o el mode d’Encaixos de fusta) són al menú de configuració de dins de cada activitat: obriu l’activitat i premeu ⚙. Es desen igualment a l’usuari que juga.</div>${checkbox('lock','Espera que acabi cada efecte','En causa-efecte, ignora les pulsacions durant l’animació, sense guardar-les per a després.')}${checkbox('waitCue','Escena aturada i enfosquida quan toca prémer','A Dia rere dia, L’orquestra que es desperta, El cel de les constel·lacions, Fem castells, Festa de globus, El vent del bosc, Muntem el robot, La flor musical i La granota bombollaire, quan acaba cada pas (o quan el vent s’ha calmat) l’escena s’atura i s’enfosqueix fins a la pulsació següent. A On anem?, Detectius de sons i La fàbrica dels disbarats, l’escena s’enfosqueix mentre l’encercament espera una pulsació per començar. Ajuda a veure quan toca tornar a prémer.')}<div class="note">A l’encercament, el marc s’atura durant la resposta del joc. No hi ha temps límit per completar una activitat.</div><button class="btn small" data-reset>Restableix els ajustos inicials</button>`}
function switchSettings(){return `<div class="field"><label for="source">Entrada del dispositiu</label><select id="source" data-string="source"><option value="keyboard" ${settings.source==='keyboard'?'selected':''}>Teclat · USB o Bluetooth que emulen tecles</option><option value="pointer" ${settings.source==='pointer'?'selected':''}>Ratolí · adaptador que emula botons</option><option value="gamepad" ${settings.source==='gamepad'?'selected':''}>Gamepad · comandament o adaptador compatible</option></select><span class="hint">Els botons tàctils en pantalla continuen disponibles. Selecciona una sola ruta del dispositiu per evitar entrades duplicades.</span></div><div class="form-grid">${[0,1].map(i=>`<section class="switch-panel"><h3><span class="switch-number">${i+1}</span>Commutador ${i+1}</h3><div class="field"><label>${settings.source==='keyboard'?'Tecla assignada':settings.source==='gamepad'?'Botó del comandament (0–31)':'Botó del ratolí'}</label>${settings.source==='keyboard'?`<button class="learn-button" data-learn="${i}">${keyName(settings.keys[i])} · Prem per canviar</button>`:settings.source==='gamepad'?`<input aria-label="Botó Gamepad ${i+1}" type="number" min="0" max="31" data-array="buttons" data-index="${i}" value="${settings.buttons[i]}">`:`<select aria-label="Botó del ratolí ${i+1}" data-array="pointer" data-index="${i}">${[[0,'Esquerre'],[1,'Central'],[2,'Dret'],[3,'Auxiliar 1'],[4,'Auxiliar 2']].map(([v,n])=>`<option value="${v}" ${settings.pointer[i]===v?'selected':''}>${n}</option>`).join('')}</select>`}</div><div class="field"><label for="hold-${i}">Pressió mínima (ms)</label><input id="hold-${i}" type="number" min="0" max="5000" step="50" data-array="hold" data-index="${i}" value="${settings.hold[i]}"><span class="hint">0: activació immediata. Només per entrades amb pressió i alliberament.</span></div><div class="field"><label for="gap-${i}">Temps entre pulsacions (ms)</label><input id="gap-${i}" type="number" min="0" max="5000" step="50" data-array="gap" data-index="${i}" value="${settings.gap[i]}"><span class="hint">Compta des de l’alliberament. 0: sense filtre de rebot.</span></div></section>`).join('')}</div><div class="test-zone"><h3>Prova els commutadors aquí</h3><p>Cap entrada de prova farà avançar el joc. Allibera el commutador entre pulsacions.</p><div class="test-lights">${[0,1].map(i=>`<div class="test-light" id="light-${i}">${i+1} · En repòs</div>`).join('')}</div><div class="test-log" id="test-log" role="status" aria-live="polite">${settings.source==='gamepad'?'Prem un botó del comandament per activar-ne la detecció.':'Esperant una entrada…'}</div><button class="btn small" data-test="0">Prova tàctil · 1</button> <button class="btn small" data-test="1">Prova tàctil · 2</button></div><div class="note">Els adaptadors que emulen Espai/Retorn o clics es configuren des del seu controlador. USB i Bluetooth descriuen la connexió, no garanteixen compatibilitat. Gamepad pendent de validació amb maquinari físic; no hi ha connexió directa WebHID/WebUSB en aquesta versió.</div>`}
function displaySettings(){const dive=page==='game'&&LOAD_DIVES.includes(game?.item?.id);return `${dive?'<h3>El fons</h3><p>Els viatges i les immersions es veuen sempre amb el decorat complet: no tenen decorat atenuat ni sense decorat.</p>':`<h3>El fons, al teu gust</h3><p>Durant una activitat, el fons es desa per a aquella activitat. Els efectes mantenen sempre la seva visibilitat.</p><div class="field"><label>Presentació del decorat</label>${segmented('background',[['full','Decorat complet'],['dim','Decorat atenuat'],['none','Sense decorat']])}</div>${settings.background==='dim'?range('opacity','Visibilitat del decorat ·',0,100,5,'%'):''}<div class="field"><label>Color de base</label>${segmented('base',[['black','Negre'],['white','Blanc']])}<span class="hint">Val per a totes les activitats que tenen decorat. Sense decorat, les figures i els efectes queden sobre el color de base, negre o blanc. Amb el decorat atenuat, el fons es veu més apagat, tant com digui «Visibilitat del decorat». Les històries (Dia rere dia, El cel de les constel·lacions, L’orquestra que es desperta, Fem castells, Festa de globus i El vent del bosc), El far, Piromusical, Muntem el robot, La flor musical, La granota bombollaire i les activitats d’encercament (excepte Gelats impossibles) comencen amb el decorat complet, com sempre; si el canvies dins d’una activitat, es desa per a aquella activitat. Caleidoscopi, Vitralls i Natura no tenen decorat, i els viatges i les immersions es veuen sempre amb el decorat complet.</span></div>`}${range('density','Densitat dels efectes escampats ·',25,100,5,'%')}${checkbox('reduced','Moviment reduït','Conserva les transformacions principals i redueix girs, salts i desplaçaments. En activar-lo també s’atura l’animació de la portada.')}${checkbox('sound','Sons del joc','Motius harmònics coordinats amb els efectes i les escenes. Sense música en repòs.')}${range('volume','Volum ·',0,100,5,'%')}<button class="btn small" data-sound-test>${icon('sound')}Escolta una mostra</button>`}
function changeSetting(key,value){try{const next=validateProfile({...settings,[key]:value});if(key==='steps'&&game&&!game.scanState&&!causeDefinition(game.item.id)?.beam&&!causeDefinition(game.item.id)?.knock&&!causeDefinition(game.item.id)?.ready){game.count=0;game.time=null;restCause(game);}if(key==='steps'&&game?.cinc)cincReset(game,next);if(key==='duration'&&game&&game.item.id==='flower'&&game.time!==null){const span=value;game.time=game.time/game.duration*span;game.duration=span;}if(key==='duration'&&game&&!vdOn(game.item.id))retimeCause(game,settings,value);settings=next;ringStyle();if((key==='sound'||key==='speakOptions')&&!value)cancelScanSpeech();storeSettings();if(game&&['background','base','opacity'].includes(key)){backgrounds[game.item.id]={background:settings.background,base:settings.base,opacity:settings.opacity};try{usWrite('backgrounds',backgrounds)}catch{}}else if(!game&&['background','base','opacity'].includes(key)){commonBackground={background:settings.background,base:settings.base,opacity:settings.opacity};try{usWrite('common-bg',commonBackground)}catch{}}$('#settings-error')&&($('#settings-error').textContent='');}catch(e){if($('#settings-error'))$('#settings-error').textContent=e.message;return false;}return true;}
function exportProfile(){const blob=new Blob([JSON.stringify({app:'Pim Pam',version:1,profile:settings,backgrounds,commonBackground},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='pim-pam-perfil.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Perfil exportat.');}
async function importProfile(file){try{if(!file||file.size>100000)throw Error('El fitxer és massa gran o no és vàlid.');const data=JSON.parse(await file.text());if(data.app!=='Pim Pam'||data.version!==1)throw Error('No és un perfil compatible de Pim Pam.');const next=validateProfile(data.profile);const imported={};if(data.backgrounds){for(const id of catalog.map(g=>g.id)){if(data.backgrounds[id]){const b=validateProfile({...defaults,...data.backgrounds[id]});imported[id]={background:b.background,base:b.base,opacity:b.opacity};}}}const cb=validateProfile({...defaults,...(data.commonBackground||next)});backgrounds=imported;commonBackground={background:cb.background,base:cb.base,opacity:cb.opacity};try{usWrite('common-bg',commonBackground);usWrite('backgrounds',backgrounds)}catch{}settings=next;storeSettings();engine.cancel();engine.resume();if(game){game.time=null;game.count=0;game.parts=[];restCause(game);if(scanDefinition(game.item.id))game.scanState=createScanState(game.item.id,settings);}drawSettings();toast('Perfil importat. Comprova els commutadors en aquest equip.');}catch(e){$('#settings-error').textContent=e.message;}}
let speechBusy=false,voiceDelay=0,speechKey='',speechToken=0,speechWatchdog=null;
function cancelScanSpeech(){speechToken++;speechBusy=false;voiceDelay=0;speechKey='';clearTimeout(speechWatchdog);try{window.speechSynthesis?.cancel();}catch{}}
function speakFocus(key,label){if(key===speechKey)return;speechKey=key;if(!settings.speakOptions||!settings.sound||paused||$('dialog[open]')||game?.cueRemaining>0)return;
 try{const synth=window.speechSynthesis,Utterance=window.SpeechSynthesisUtterance;if(!synth||!Utterance)return;const voice=synth.getVoices().find(v=>/^ca(?:-|_|$)/i.test(v.lang));if(!voice)return;const token=++speechToken;synth.cancel();const u=new Utterance(label);u.voice=voice;u.lang=voice.lang;u.rate=.95;speechBusy=true;const ended=()=>{if(token!==speechToken)return;speechBusy=false;voiceDelay=settings.scanVoiceGap;};u.onend=ended;u.onerror=ended;clearTimeout(speechWatchdog);speechWatchdog=setTimeout(ended,8000);synth.speak(u);}catch{speechBusy=false;}
}
// Detectius de sons: the clue of the round, a short phrase of one of the recorded instruments; D'on ve aquest so?: the sound of the place
// alone (0.18). It waits for the recordings to be decoded (at most 4 s), so that no built-in imitation ever plays it; the scanning waits
// while it sounds.
function playTargetCue(){if(!game?.scanState||!scanCued(game.item.id))return;cancelScanSpeech();stopSound();tasteStop(.1);audioStart();game.cueWanted=0;if(game.persona){const d=psCue(game);game.cueRemaining=(d+.6)*1000;game.scanState.cueNeeded=false;return;}const clue=game.item.id==='sources'?ogClue(game.scanState.round):tmClue(game.scanState.round,settings);
 if(settings.sound&&synth&&audio?.state==='running')for(const n of clue.notes){synth.play(boardEvent(n),audio.currentTime+.12+n.t,n.len);soundLog('play',{bus:'main',event:boardEvent(n),delay:.12+n.t,length:n.len});}game.cueRemaining=(clue.length+.6)*1000;game.scanState.cueNeeded=false;}
// The highlight of the focus (0.17): the kind of frame, its colour, its thickness and the relief, with a sample that shows them.
const SCAN_COLOR_NAMES={orange:'Taronja',yellow:'Groc',red:'Vermell',pink:'Rosa',green:'Verd',blue:'Blau',white:'Blanc',black:'Negre'};
function ringSettings(){const r=scanRing(settings);return `<h3>Ressaltat del focus</h3><div class="field"><label>Marc del focus</label>${segmented('scanFrame',[['progress','Es va dibuixant'],['whole','Sencer, salta d’opció en opció'],['none','Sense marc']])}<span class="hint">El marc que es va dibuixant mostra el temps que queda a cada opció en l’encercament automàtic. El marc sencer es veu complet des del principi. Amb dos commutadors el marc sempre és sencer. Sense marc, el focus es marca només amb la capa de color.</span></div>
 <div class="field"><label>Capa de color</label>${segmented('scanFill',[['none','Sense capa'],['whole','Sencera'],['grow','Creix d’esquerra a dreta']])}<span class="hint">Una capa semitransparent del color del ressaltat cobreix tot l’interior del marc. Pot anar sola o amb el marc. La que creix d’esquerra a dreta s’omple amb el temps de cada opció, sobre una capa pàl·lida sencera; amb dos commutadors sempre és sencera.</span></div>
 ${range('scanFillAlpha','Opacitat de la capa ·',20,70,5,'%')}
 <div class="field"><label>Color del ressaltat</label><div class="segmented swatches" role="group">${Object.entries(SCAN_COLORS).map(([k,c])=>`<button data-setting="scanColor" data-value="${k}" class="${settings.scanColor===k?'active':''}" aria-pressed="${settings.scanColor===k}"><span class="swatch" style="background:${c}"></span>${SCAN_COLOR_NAMES[k]}</button>`).join('')}</div></div>
 ${range('scanWidth','Gruix del ressaltat ·',4,24,2,' px')}${checkbox('scanRelief','Ressaltat amb relleu','Afegeix una ombra sota el marc i una llum al llarg del traç, perquè destaqui encara més.')}
 <div class="ring-sample${r.frame!=='progress'?' ring-whole':''}${r.relief?' ring-relief':''}${r.frame==='none'?' ring-none':''}${r.fill!=='none'?' fill-on':''}${r.fill==='grow'?' fill-grow':''}" style="--ring-c:${r.color};--ring-edge:${r.edge};--ring-track:${r.track};--ring-w:${r.width}px;--fill-a:${r.fillAlpha}" aria-hidden="true"><span class="choice scanned" style="--ring-p:62">${RING_SVG}<span>Mostra</span></span></div>`;}
function scanSettings(){return `${ringSettings()}<h3>Encercament i tipus d’activitat</h3><div class="form-grid"><div class="field"><label for="scanOptions">Opcions de contingut</label><select id="scanOptions" data-number="scanOptions">${[2,3,4].map(n=>`<option value="${n}" ${settings.scanOptions===n?'selected':''}>${n} opcions</option>`).join('')}</select><span class="hint">Algunes categories tenen tres alternatives. El jardí conserva quatre parcel·les.</span></div><div class="field"><label for="scanStart">Inici de l’encercament</label><select id="scanStart" data-string="scanStart"><option value="auto" ${settings.scanStart==='auto'?'selected':''}>Automàtic en entrar</option><option value="manual" ${settings.scanStart==='manual'?'selected':''}>Primera pulsació per començar</option></select></div><div class="field"><label for="scanDirection">Sentit del recorregut</label><select id="scanDirection" data-string="scanDirection"><option value="forward" ${settings.scanDirection==='forward'?'selected':''}>Endavant</option><option value="reverse" ${settings.scanDirection==='reverse'?'selected':''}>Enrere</option></select></div><div class="field"><label for="scanReturn">Retorn després d’una tria diferent</label><select id="scanReturn" data-string="scanReturn"><option value="first" ${settings.scanReturn==='first'?'selected':''}>Primera opció</option><option value="selected" ${settings.scanReturn==='selected'?'selected':''}>Opció que s’havia triat</option></select></div><div class="field"><label for="scanFirst">Temps extra a la primera opció (ms)</label><input id="scanFirst" type="number" data-number="scanFirst" min="0" max="5000" step="100" value="${settings.scanFirst}"></div><div class="field"><label for="scanLaps">Voltes abans d’esperar una pulsació</label><select id="scanLaps" data-number="scanLaps">${[0,1,2,3,5].map(n=>`<option value="${n}" ${settings.scanLaps===n?'selected':''}>${n===0?'Sense límit':n+' voltes'}</option>`).join('')}</select></div></div><div class="form-grid"><div class="field"><label for="boardTaste">Tast en el focus (taulers a pantalla completa)</label><select id="boardTaste" data-string="boardTaste"><option value="sound" ${settings.boardTaste==='sound'?'selected':''}>El so de cada opció</option><option value="click" ${settings.boardTaste==='click'?'selected':''}>Un clic de fusta suau</option><option value="off" ${settings.boardTaste==='off'?'selected':''}>Cap so</option></select><span class="hint">Quan una opció d’un tauler a pantalla completa té el focus (una porta, un instrument, un paisatge, un color o una música dels focs), sona un tast breu del seu so (d’1 a 1,4 s), que es talla quan el focus avança. Amb la locució activada, la veu el substitueix.</span></div></div>${checkbox('switchHint','Pista del commutador','Si l’encercament fa una volta sencera sense cap pulsació, o espera una pulsació per començar, a baix al centre parpelleja suaument el dibuix d’un commutador (amb dos commutadors, n’hi ha dos). Tocar-lo és com prémer el commutador. Durant les activitats d’encercament no hi ha cap paraula escrita.')}${checkbox('speakOptions','Locució de les opcions','Utilitza una veu catalana instal·lada i disponible al navegador. Si no n’hi ha, es conserven les etiquetes, els dibuixos i els sons.') }<div class="field"><label for="scanVoiceGap">Espera després de la locució (ms)</label><input id="scanVoiceGap" data-number="scanVoiceGap" type="number" min="0" max="3000" step="100" value="${settings.scanVoiceGap}"></div>`;}
function about(){openSettings();$('#settings .dialog-body').innerHTML=`<h3>Pim Pam · Desenvolupament 0.50.3</h3><p>44 activitats: 33 de causa-efecte i 11 d’encercament, i la carpeta «Activitats personalitzades».</p><p>La 0.50.3 canvia el botó «Alta qualitat» per «Versió WebGL 2» i el posa a la part de baix de la fitxa.</p><p>La 0.50.2 passa els vídeos dels cinc viatges i immersions a 30 fotogrames per segon (abans 60): costen la meitat de descodificar i ocupen un 16 % menys. A la part de baix de cada fitxa d’aquestes activitats hi ha el botó «Versió WebGL 2», que les obre amb el motor original dibuixat en directe en lloc del vídeo (més requisits de maquinari).</p><p>La 0.50.1 canvia el nom de la segona pel·lícula a «Comunicar a tot arreu sempre». La 0.50 hi afegeix la carpeta «Petites pel·lícules», just després d’«Històries pas a pas», amb dues pel·lícules curtes: «Un mos a Barcelona» (deu seqüències) i «Comunicar a tot arreu sempre» (onze). Cada pulsació mostra una seqüència; quan s’acaba, la imatge s’atura i s’enfosqueix fins a la pulsació següent, i després de l’última es torna a començar. Els vídeos es carreguen des del web; sense connexió (el fitxer únic) cal tenir la carpeta «videos» al costat del fitxer.</p><p>La 0.49 reprodueix en vídeo (1080p, amb la seva música) les vint escenes dels cinc viatges i immersions: «Fons marí de vidre», «Selva de llum», «Sabana de paper», «El pou del temps» i «Gegants del blau». Les tauletes ja no les han de dibuixar en directe. Aquestes activitats es veuen sempre amb el decorat complet. Sense connexió (el fitxer únic), es continuen dibuixant en directe. El lema és ara «Un petit gest. Un gran efecte.»</p><p>La 0.48 renova «Detectius de sons»: vint instruments reals (gravacions noves de VSCO-2 CE), dibuixos nous, el model que es busca en un marc gran a dalt, caselles més petites i sense lupa.</p><p>La 0.47.3 treu tres activitats: «Jardí de paper», «La llenyataire» i «La caixa sorpresa».</p><p>La 0.47.2 refà les imatges d’«El viatge en globus» de la targeta del menú i del panell ⓘ amb el globus nou.</p><p>La 0.47.1 redibuixa el globus d’«El viatge en globus» amb la forma d’un globus aerostàtic de veritat (vela de forma natural amb vint gaies, boca amb faldó, cables, cremador i cistella), treu els núvols i la boira que es veien tallats, i posa la carpeta «Formes, llum i música» en primer lloc a la pàgina inicial.</p><p>La 0.47 hi afegeix «La fira de llauna», a la carpeta «Prémer al moment»: una fira de joguines de llauna estampada on tres bombetes s’encenen d’una en una amb tres notes que pugen, i quan s’encén la tercera és el moment de prémer. Hi ha cinc atraccions (les bitlles catalanes, el canó de la bala humana, el coet de corda, la força i la cursa de cavallets) amb sis sorpreses i un final cadascuna, i quatre llums del dia: vint rondes. Els ajustos propis (ritme de les bombetes, calma, què passa si es prem abans d’hora, quant espera la figura i la primera atracció) són a la pestanya «Aquesta activitat».</p><p>La 0.46.1 treu l’apartat «El recorregut» i els botons «Els jocs» i «El recorregut» de dalt del menú; els botons petits de la cantonada de cada activitat mostren una etiqueta en passar-hi el cursor (Informació, Pausa, Configuració, Surt), la pausa té una icona de dues barres en lloc de la xifra romana, i s’ha tret el de la fletxa en diagonal: per sortir, la casa. La 0.46 hi afegeix usuaris opcionals. Sense fer res, es juga com a convidat; qui vulgui pot crear un usuari només amb un nom, sense contrasenya, que guarda en aquest dispositiu els seus ajustos, els preferits, les seves activitats personalitzades i un registre del que juga, que es pot consultar i exportar. Els usuaris es poden exportar i importar en un fitxer. Els ajustos propis de cada activitat ara només surten al menú de configuració de dins de l’activitat, a la pestanya «Aquesta activitat». I les activitats personalitzades tenen una mecànica nova, «Vídeo a poc a poc»: el vídeo avança a cada pulsació i a cada pausa s’atura i la pantalla s’enfosqueix fins a la pulsació següent, cada pocs segons o als moments que hi marqueu.</p><p>La 0.45.10 fa que a «Fem castells» cada pis s’enfili a poc a poc durant tot el tros de música de la seva pulsació i que l’enxaneta faci l’aleta dos segons més. La 0.45.9 fa que «Fem castells» pugi un pis a cada pulsació (set pulsacions: la pinya amb els baixos, els segons, els terços, els quarts, els dosos, l’aixecador i l’enxaneta). La 0.45.8 hi posa un toc de castells de veritat, de gralles i timbal, que avança un tros a cada pulsació; amb l’enxaneta sona el final de les gralles i els aplaudiments de la plaça. La 0.45.7 hi fa els castellers més realistes i la 0.45.6 hi afegeix el color de la camisa. La 0.45.2 fa que l’encercament d’«Estiu a la masia» vagi sempre d’esquerra a dreta per l’escena. La 0.45.5 fa que l’halo del forat objectiu d’«Encaixos de fusta» respiri sense créixer, com una llum esvaïda enganxada al contorn. La 0.45.1 marca el forat objectiu d’«Encaixos de fusta» amb un contorn groc gruixut que respira. La 0.45 estrena «Encaixos de fusta» (EN12), que substitueix «Puzles que cobren vida», una de les primeres activitats: un trencaclosques de fusta pintada que omple tota la pantalla, amb cinc mons (el port, el circ, la ciutat, el bosc i l’espai) i quatre llums per món, vint taulers; vint-i-cinc figures de fusta articulades amb dues històries cadascuna; música per capes (cada peça posada hi afegeix una veu: percussió, baix, acords, melodia) i sons dels bancs ja enregistrats, sense cap enregistrament nou. És a la carpeta «Encercament: relacionar». Ajustos nous a la pestanya general: mode Encaixa o Lliure, pista al forat (imatge o silueta), semblança de les peces, ajuda després de 2 o 3 errors, llum al forat marcat i ritme. La 0.44.7 treu les línies que es veien sobre els parasaurolophus en algunes targetes gràfiques (la textura fina de la pell, que s’hauria d’esvair, hi apareixia trencada): ara la pell és llisa amb una lluentor suau, a l’escena 11 i també als triceratops, l’anquilosaure, els iguanodonts i l’estegosaure, que feien servir el mateix recurs. La 0.44.6 torna a fer que les escenes d’«El pou del temps» es preparin tan de pressa com abans de la pell nova dels parasaurolophus: la pell nova queda tota dins de l’escena 11, sense tocar el codi comú de les vint escenes. La 0.44.5 millora la història d’en Pol a «Estiu a la masia»: el llençol cau obert damunt del cap de l’avi i el cobreix de dalt a baix, la cara de l’avi ja no queda darrere del paller i la gorra d’en Pol es dibuixa com una gorra de visera. La 0.44.4 fa que «El pou del temps» no es quedi aturat en prémer quan una escena encara s’està preparant a la targeta gràfica (per exemple després del mamut): mentre es prepara es veu la roca i l’escena anterior, i la nova apareix tan aviat com està a punt. La 0.44.3 corregeix «Estiu a la masia»: l’encercament passa per tots els personatges que queden des del principi, en Pol es queda dins del paller després de caure-hi, el collar de la cabra segueix el coll i, en anar al sopar, la cabra puja pel camí en lloc de travessar el llac. La 0.44.2 redissenya de nou la pell dels parasaurolophus de l’escena 11 d’«El pou del temps»: sense cap textura fina, amb tres tons (ventre clar, flancs i llom fosc), franges fosques irregulars sobre el llom i la cua, taques clares disperses als flancs i una llum satinada de pell humida. La 0.44.1 posa aquesta carpeta al final del menú. La 0.44 hi afegeix un creador d’activitats amb les fotos, els vídeos i la música que la família o els professionals aporten per a cada infant, sobre cinc mecàniques de Pim Pam: Àlbum de sorpreses, Descobreix pas a pas, Qui s’amaga?, Tria i mira i Escolta i troba. Les activitats es desen només en aquest dispositiu i es poden exportar i importar, totes alhora o una per una.</p><p>La 0.43.1 passa «La granota bombollaire» de la carpeta «Mantenir premut» a «Històries pas a pas». La 0.43 afegeix «El viatge en globus» (CE43), l’última activitat de mantenir premut: mentre es manté premut el commutador el cremador s’encén i el globus puja; en deixar-lo anar, baixa a poc a poc. Vint viatges (cinc rutes i quatre estacions), cadascun un dia sencer de l’albada a la matinada, amb la Mila i el seu gos Bru.</p><p> La 0.42 ordena la pàgina principal en carpetes segons com es juga (viatges, formes i música, històries pas a pas, prémer al moment, mantenir premut, encercament per triar i per relacionar) i guarda a part, a «Per revisar», les primeres activitats fetes amb ChatGPT.</p><p>La 0.41 corregeix l’ordre de les capes a «Estiu a la masia» (l’àvia es veu a la finestra de pit en amunt, l’avi seu de manera natural i els objectes queden darrere dels personatges), refà la pell dels parasaurolophus de l’escena 11 d’«El pou del temps» sense quadrícula d’escates, i fa que «El vent del bosc», «El pou del temps» i les altres immersions s’obrin abans i vagin més llises en ordinadors amb targeta gràfica integrada.</p><p>La 0.40.1 fa que «Estiu a la masia» s’obri de pressa en ordinadors amb targeta gràfica integrada (els seus panorames es pinten amb el processador) i que l’anell de càrrega es vegi de seguida a les activitats que tarden a obrir-se. Novetats de la 0.40: el focus de l’encercament pot portar, a més del marc o en lloc d’ell, una capa semitransparent del mateix color que cobreix tot l’interior de l’opció, sencera o creixent d’esquerra a dreta amb el temps de cada opció (Configuració › Encercament › Ressaltat del focus). I cada activitat s’obre darrere una pantalla de càrrega amb un anell de progrés i no apareix fins que té a punt els sons, les imatges i els gràfics; els sons gravats es preparen mentre el menú és obert, de manera que la majoria d’activitats s’obren de seguida.</p><p>De la 0.39: «Estiu a la masia» (EN26), un tauler d’encercament entre cinc personatges d’una masia pintada com en una pel·lícula d’animació 2D, cadascun amb la seva petita història divertida.</p><p>Les activitats d’encercament es juguen amb un o dos commutadors; les de causa-efecte, amb un. Tot funciona sense connexió, en un sol fitxer.</p>`;}
// ---------- 0.46 · Usuaris: who plays, the users of this device and the record of each one ----------
// Marc, 6 November 2026: playing as guest needs nothing; a user is only a name (no password) and keeps its settings, its personalised
// activities and the record of what it played on this device; users can be exported and imported. The dialog is for adults.
function logEnd(){const g=game,L=g?.log;if(!L||L.done)return;L.done=true;if(usIsGuest())return;const d=Math.round(L.d);if(d<3&&!L.n)return;const it=g.item;
 usLogAdd({t:L.t,id:it.id,code:it.code,name:it.persona?(psAct(it.id)?.name||'Activitat personalitzada'):it.name,type:it.type,d,n:L.n,p:L.p,persona:!!it.persona});}
function switchUser(id){if(id===usCurrent())return;logEnd();if(!usSwitch(id))return;loadUser();engine.settings=settings;engine.cancel();engine.resume();folder=folder===PS_FOLDER||folder==='favorites'?folder:null;
 psSetOwner(id).then(()=>{if(page==='home')home();}).catch(()=>{});closeUsers(false);home();toast(`Ara juga ${usName()}.`);}
let usersCounts=new Map(),usersMsg='';
async function openUsers(){if($('dialog[open]'))return;lastFocus=document.activeElement;const d=document.createElement('dialog');d.className='dialog users-dialog';d.id='users';d.setAttribute('aria-label','Usuaris d’aquest dispositiu');document.body.append(d);
 d.addEventListener('cancel',e=>{if(e.target!==d)return;e.preventDefault();closeUsers();});usersMsg='';drawUsers();d.showModal();usersCounts=await ufCounts();drawUsers();}
function closeUsers(focus=true){const d=$('#users');if(d){d.close();d.remove();}engine.cancel();engine.resume();if(focus&&lastFocus?.isConnected)lastFocus.focus();}
const fmtDate=t=>{try{return new Date(t).toLocaleDateString('ca',{day:'numeric',month:'long',year:'numeric'});}catch{return usDay(t);}};
function userRow(id){const cur=id===usCurrent(),u=usUser(id),guest=id===US_GUEST,acts=usersCounts.get(id)||0,log=guest?[]:usLog(id),last=log.length?log[log.length-1].t:0;
 const meta=guest?'Per defecte. Els ajustos es desen al dispositiu; no guarda registre.':`${acts} ${acts===1?'activitat personalitzada':'activitats personalitzades'} · ${log.length} ${log.length===1?'sessió':'sessions'}${last?' · última: '+fmtDate(last):''}`;
 return `<li class="user-row${cur?' current':''}">${userBadge(id)}<div class="user-info"><strong>${escape(usName(id))}</strong>${cur?'<span class="user-now">Juga ara</span>':''}<small>${meta}</small></div><div class="user-actions">${cur?'':`<button type="button" class="btn small primary" data-user-enter="${id}">Entra</button>`}${guest?'':`<button type="button" class="btn small" data-user-log="${id}">Registre</button><button type="button" class="btn small" data-user-rename="${id}">Canvia el nom</button><button type="button" class="btn small" data-user-export="${id}">${icon('download')}Exporta</button><button type="button" class="btn small pe-danger" data-user-delete="${id}">Esborra</button>`}</div></li>`;}
function drawUsers(){const d=$('#users');if(!d)return;const list=usList(),keep=$('#user-new-name')?.value||'';
 d.innerHTML=`<div class="dialog-head"><div class="dialog-title"><h2>Qui juga?</h2><button class="icon-button" data-close-users aria-label="Tanca">${icon('close')}</button></div><p>Sense fer res, es juga com a convidat. Un usuari només té un nom, sense contrasenya, i guarda en aquest dispositiu els seus ajustos, els preferits, les seves activitats personalitzades i el registre del que juga.</p></div>
 <div class="dialog-body"><ul class="user-list">${userRow(US_GUEST)}${list.map(u=>userRow(u.id)).join('')}</ul>
 <h3>Usuari nou</h3><div class="user-new"><div class="field"><label for="user-new-name">Nom</label><input id="user-new-name" maxlength="40" autocomplete="off" placeholder="Per exemple: Martina" value="${escape(keep)}"></div><button type="button" class="btn primary" data-user-create>Crea’l i entra ${icon('arrow')}</button></div>
 <label class="check-row"><span>Comença amb els ajustos de qui juga ara<small>Els commutadors, l’encercament, la imatge i el so, els ajustos de cada activitat i els preferits de ${escape(usName())}. Si no, comença amb els ajustos inicials.</small></span><input type="checkbox" id="user-copy" checked></label>
 <h3>En aquest dispositiu</h3><label class="check-row"><span>En obrir Pim Pam, entra com l’últim usuari<small>Si no, Pim Pam s’obre sempre com a convidat.</small></span><input type="checkbox" id="user-remember" ${usRemember()?'checked':''}></label>
 <div class="profile-actions users-files"><button type="button" class="btn small" data-users-import>Importa usuaris</button><button type="button" class="btn small" data-users-export-all ${list.length?'':'disabled'}>${icon('download')}Exporta’ls tots</button><input class="hidden" id="users-import-file" type="file" accept=".zip,application/zip" multiple></div>
 <div id="users-status" class="note" role="status" ${usersMsg?'':'hidden'}>${escape(usersMsg)}</div>
 <div class="note">Sense contrasenya: qualsevol persona que faci servir aquest dispositiu pot entrar a qualsevol usuari i veure’n el registre. Les dades no surten d’aquest navegador si no les exporteu. Un usuari exportat porta els seus ajustos, el registre i les seves activitats personalitzades amb les fotos, els vídeos i la música; en importar-lo a un altre equip, cal comprovar-hi els commutadors.</div>
 <div class="dialog-actions"><span></span><button class="btn primary" data-close-users>Fet ${icon('check')}</button></div></div>`;}
function usersStatus(msg){usersMsg=msg||'';const el=$('#users-status');if(el){el.hidden=!usersMsg;el.textContent=usersMsg;}}
function createUser(){const name=($('#user-new-name')?.value||'').trim();if(!name){usersStatus('Escriviu el nom del nou usuari.');$('#user-new-name')?.focus();return;}const u=usCreate(name,$('#user-copy')?.checked?usCurrent():null);switchUser(u.id);}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),60000);}
async function exportUsers(ids){usersStatus('Preparant l’exportació…');try{const r=await ufExport(ids);downloadBlob(r.blob,r.name);usersStatus(`${r.users===1?'Usuari exportat':r.users+' usuaris exportats'}${r.acts?`, amb ${r.acts} ${r.acts===1?'activitat personalitzada':'activitats personalitzades'}`:''} (${(r.blob.size/1e6).toFixed(1).replace('.',',')} MB).`);}catch(e){usersStatus('No s’ha pogut exportar: '+(e?.message||e));}}
async function importUsers(files){const done=[];let added=0;for(const f of files){usersStatus(`Important ${f.name}…`);try{const r=await ufImport(f);done.push(...r.users);added+=r.added;}catch(e){usersStatus((e?.name==='QuotaExceededError'?'No hi ha prou espai al dispositiu.':'No s’ha pogut importar «'+f.name+'»: '+(e?.message||e)));return;}}
 if(done.some(r=>r.user.id===usCurrent())){loadUser();engine.settings=settings;}await psSetOwner(usCurrent()).catch(()=>{});usersCounts=await ufCounts();usersMsg=done.length?`${done.map(r=>`${r.user.name}${r.replaced?' (actualitzat)':''}`).join(', ')}: ${done.length===1?'importat':'importats'}${added?`, amb ${added} ${added===1?'activitat personalitzada':'activitats personalitzades'}`:''}. Comproveu els commutadors en aquest equip.`:'El fitxer no tenia cap usuari.';drawUsers();}
async function deleteUser(id){const u=usUser(id);if(!u)return;const acts=usersCounts.get(id)||0;if(!confirm(`Voleu esborrar l’usuari «${u.name}»? S’esborren d’aquest dispositiu els seus ajustos, el registre${acts?` i ${acts===1?'la seva activitat personalitzada':`les seves ${acts} activitats personalitzades`}`:''}, i no es pot desfer. Si el voleu conservar, exporteu-lo abans.`))return;
 const wasCur=id===usCurrent();try{await ufDeleteActs(id);}catch{}usDelete(id);usersCounts=await ufCounts();if(wasCur){loadUser();engine.settings=settings;await psSetOwner(usCurrent()).catch(()=>{});home();}usersMsg=`S’ha esborrat «${u.name}».`;if($('#users'))drawUsers();else openUsers();}
function renameUser(id){const u=usUser(id);if(!u)return;const name=prompt('Nou nom de l’usuari:',u.name);if(name===null||!name.trim())return;const r=usRename(id,name);if(id===usCurrent()){settings={...settings,name:r.name};storeSettings();}drawUsers();if(page==='home'){const chip=$('.user-chip');if(chip)chip.outerHTML=userChip();}}
// The record of a user: the totals, every activity with how often and how long it was played, and day by day what was played.
let logShown=150;
function openLog(id){const prev=$('#users');if(prev){prev.close();prev.remove();}logShown=150;const d=document.createElement('dialog');d.className='dialog log-dialog';d.id='user-log';d.dataset.user=id;d.setAttribute('aria-label','Registre d’activitat');document.body.append(d);d.addEventListener('cancel',e=>{if(e.target!==d)return;e.preventDefault();closeLog();});drawLog();d.showModal();}
function closeLog(){const d=$('#user-log');if(d){d.close();d.remove();}openUsers();}
function drawLog(){const d=$('#user-log');if(!d)return;const id=d.dataset.user,log=usLog(id),S=usSummary(log),name=usName(id),rows=[...log].reverse(),shown=rows.slice(0,logShown),days=new Map();
 for(const e of shown){const k=usDay(e.t);if(!days.has(k))days.set(k,[]);days.get(k).push(e);}
 const dayTotal=k=>log.filter(e=>usDay(e.t)===k);const hm=t=>{const x=new Date(t);return `${String(x.getHours()).padStart(2,'0')}:${String(x.getMinutes()).padStart(2,'0')}`;};
 const dayHead=k=>{const all=dayTotal(k),t=all.reduce((a,e)=>a+e.d,0);let label=k;try{label=new Date(all[0].t).toLocaleDateString('ca',{weekday:'long',day:'numeric',month:'long',year:'numeric'});}catch{}return `<h4>${escape(label)} <small>${all.length} ${all.length===1?'activitat':'activitats'} · ${usDuration(t)}</small></h4>`;};
 d.innerHTML=`<div class="dialog-head"><div class="dialog-title"><h2>Registre de ${escape(name)}</h2><button class="icon-button" data-close-log aria-label="Tanca">${icon('close')}</button></div><p>Cada línia és una vegada que s’ha obert una activitat: quan, quanta estona s’hi ha jugat (sense comptar les pauses ni la configuració) i quantes pulsacions s’han acceptat; a l’encercament, també quantes tries s’han fet. Es desa només en aquest dispositiu.</p></div>
 <div class="dialog-body">${log.length?`<div class="log-tiles"><div><strong>${S.sessions}</strong><span>${S.sessions===1?'sessió':'sessions'}</span></div><div><strong>${usDuration(S.time)}</strong><span>de joc</span></div><div><strong>${S.days}</strong><span>${S.days===1?'dia':'dies'}</span></div><div><strong>${S.presses}</strong><span>pulsacions</span></div></div>
 <h3>Per activitat</h3><div class="log-table-wrap"><table class="log-table"><thead><tr><th>Activitat</th><th>Vegades</th><th>Temps</th><th>Pulsacions</th><th>Última vegada</th></tr></thead><tbody>${S.activities.map(a=>`<tr><td><span class="log-code">${escape(a.code)}</span>${escape(a.name)}</td><td>${a.times}</td><td>${usDuration(a.d)}</td><td>${a.n}${a.type==='scan'&&a.p?` · ${a.p} ${a.p===1?'tria':'tries'}`:''}</td><td>${escape(fmtDate(a.last))}</td></tr>`).join('')}</tbody></table></div>
 <h3>Dia a dia</h3><div class="log-days">${[...days.entries()].map(([k,list])=>`${dayHead(k)}<ul>${list.map(e=>`<li><span class="log-time">${hm(e.t)}</span><span class="log-name"><span class="log-code">${escape(e.code)}</span>${escape(e.name)}</span><span class="log-d">${usDuration(e.d)}</span><span class="log-n">${e.n} ${e.n===1?'pulsació':'pulsacions'}${e.type==='scan'?` · ${e.p} ${e.p===1?'tria':'tries'}`:''}</span></li>`).join('')}</ul>`).join('')}</div>
 ${rows.length>logShown?`<button type="button" class="btn small" data-log-more>Mostra’n més (${rows.length-logShown} més)</button>`:''}`:'<p class="empty">Encara no hi ha res al registre. Cada activitat que s’obre amb aquest usuari hi afegeix una línia en sortir-ne.</p>'}
 <div class="dialog-actions"><div class="profile-actions"><button type="button" class="btn small" data-log-csv ${log.length?'':'disabled'}>${icon('download')}Exporta’l (CSV)</button><button type="button" class="btn small pe-danger" data-log-clear ${log.length?'':'disabled'}>Esborra el registre</button></div><button class="btn primary" data-close-log>Fet ${icon('check')}</button></div></div>`;}
function usersClick(b){const ds=b.dataset;
 if(b.hasAttribute('data-users')){if($('#settings'))closeSettings();openUsers();return true;}if(b.hasAttribute('data-close-users')){closeUsers();return true;}
 if(ds.userEnter){switchUser(ds.userEnter);return true;}if(b.hasAttribute('data-user-create')){createUser();return true;}if(ds.userLog){openLog(ds.userLog);return true;}if(ds.userRename){renameUser(ds.userRename);return true;}
 if(ds.userExport){exportUsers([ds.userExport]);return true;}if(b.hasAttribute('data-users-export-all')){exportUsers(usList().map(u=>u.id));return true;}if(b.hasAttribute('data-users-import')){$('#users-import-file')?.click();return true;}
 if(ds.userDelete){deleteUser(ds.userDelete);return true;}if(b.hasAttribute('data-close-log')){closeLog();return true;}if(b.hasAttribute('data-log-more')){logShown+=300;drawLog();return true;}
 if(b.hasAttribute('data-log-csv')){const id=$('#user-log')?.dataset.user;if(id){downloadBlob(new Blob([usCsv(usLog(id),usName(id))],{type:'text/csv;charset=utf-8'}),`pim-pam-registre-${usName(id).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'usuari'}-${usDay(Date.now())}.csv`);}return true;}
 if(b.hasAttribute('data-log-clear')){const id=$('#user-log')?.dataset.user;if(id&&confirm(`Voleu esborrar tot el registre de «${usName(id)}»? No es pot desfer. Si el voleu conservar, exporteu-lo abans.`)){usLogClear(id);drawLog();}return true;}
 return false;}
document.addEventListener('change',e=>{const t=e.target;if(t.id==='user-remember')usSetRemember(t.checked);if(t.id==='users-import-file'&&t.files?.length){const f=[...t.files];t.value='';importUsers(f);}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target?.id==='user-new-name'){e.preventDefault();createUser();}},true);
// Delegated UI actions preserve a single set of listeners across routes.
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(usersClick(b))return;if(b.hasAttribute('data-home')){e.preventDefault();home();}else if(b.dataset.startHq)start(b.dataset.startHq,{live:true});else if(b.dataset.start)start(b.dataset.start);else if(b.hasAttribute('data-folder'))openFolder(b.dataset.folder);else if(b.dataset.nav){home();}else if(b.hasAttribute('data-ps-new'))peOpen(null);else if(b.dataset.psEdit)peOpen(b.dataset.psEdit);else if(b.dataset.psExport)peExport(b.dataset.psExport);else if(b.hasAttribute('data-ps-export-all'))peExport(null);else if(b.dataset.psDelete)peDelete(b.dataset.psDelete);else if(b.hasAttribute('data-ps-import'))$('#ps-import-file')?.click();else if(b.hasAttribute('data-info'))openInfo(b.dataset.info);else if(b.hasAttribute('data-close-info'))closeInfo();else if(b.hasAttribute('data-settings'))openSettings();else if(b.hasAttribute('data-close-settings'))closeSettings();else if(b.dataset.tab){modalTab=b.dataset.tab;learn=null;drawSettings();}else if(b.dataset.filter){filter=b.dataset.filter;scan.reset();home();}else if(b.dataset.favorite){const id=b.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];try{usWrite('favorites',favorites)}catch{}home();}else if(b.hasAttribute('data-menu-scan')){homeScan=!homeScan;scan.reset();home();}else if(b.hasAttribute('data-pause')){paused?resumeGame():pauseGame();}else if(b.hasAttribute('data-resume'))resumeGame();else if(b.hasAttribute('data-sound')){changeSetting('sound',!settings.sound);if(!settings.sound)stopSound();else audioStart();b.innerHTML=icon(settings.sound?'sound':'mute');b.setAttribute('aria-label',`${settings.sound?'Desactiva':'Activa'} el so`);}else if(b.hasAttribute('data-fullscreen')){if(document.fullscreenElement||$('.game-wrap')?.classList.contains('immersive')){home();}else{$('.game-wrap')?.classList.add('immersive');requestFull();}}else if(b.hasAttribute('data-choice')){if(engine.pending||e.detail>0&&performance.now()<capturedChoiceClickUntil)return;select(+b.dataset.choice);}else if(b.dataset.setting){const v=b.dataset.setting==='mode'?+b.dataset.value:b.dataset.value;if(b.dataset.setting==='scanFrame'&&v==='none'&&settings.scanFill==='none')changeSetting('scanFill','whole');if(b.dataset.setting==='scanFill'&&v==='none'&&settings.scanFrame==='none')changeSetting('scanFrame','whole');if(changeSetting(b.dataset.setting,v))drawSettings();}else if(b.hasAttribute('data-learn')){learn=+b.dataset.learn;b.textContent='Prem la nova tecla… · Esc per cancel·lar';b.classList.add('learning');}else if(b.hasAttribute('data-export'))exportProfile();else if(b.hasAttribute('data-import'))$('#import-file').click();else if(b.hasAttribute('data-reset')){settings=structuredClone(defaults);backgrounds={};commonBackground={background:'none',base:'black',opacity:25};try{usWrite('common-bg',commonBackground)}catch{};try{usWrite('backgrounds',{})}catch{}storeSettings();if(game){game.time=null;game.count=0;game.parts=[];restCause(game);if(scanDefinition(game.item.id))game.scanState=createScanState(game.item.id,settings);}drawSettings();toast('Ajustos inicials restablerts.');}else if(b.hasAttribute('data-sound-test')){audioStart();chord([261.63,392,523.25],.7);}else if(b.hasAttribute('data-about'))about();else if((b.hasAttribute('data-switch')||b.hasAttribute('data-test'))&&e.detail===0){engine.pulse(+(b.dataset.switch??b.dataset.test),'virtual');}});
// The sample of the highlight in the settings follows the profile while it changes.
function ringSample(){ringStyle();const el=$('.ring-sample');if(!el)return;ringApply(el,scanRing(settings),false);}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.range){changeSetting(t.dataset.range,+t.value);const out=$('#out-'+t.dataset.range);if(out)out.textContent=t.value+(t.dataset.range==='scanTime'?' ms':t.dataset.range==='scanWidth'?' px':'%');ringSample();if(master)master.gain.value=loading?0:settings.volume/100*.35;}if(t.id==='profile-name')changeSetting('name',t.value);});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.check){changeSetting(t.dataset.check,t.checked);if(!settings.sound)stopSound();ringSample();}if(t.dataset.number)changeSetting(t.dataset.number,+t.value);if(t.dataset.string){changeSetting(t.dataset.string,t.value);engine.cancel();engine.releaseAll();engine.resume();drawSettings();}if(t.dataset.array){const arr=[...settings[t.dataset.array]];arr[+t.dataset.index]=+t.value;if(!changeSetting(t.dataset.array,arr))t.value=settings[t.dataset.array][+t.dataset.index];}if(t.id==='import-file')importProfile(t.files[0]);if(t.id==='ps-import-file'&&t.files?.length){peImport(t.files[0]);t.value='';}});
let activePointers=new Map(),lastPointerTime=-Infinity,capturedChoiceClickUntil=-Infinity;
function pointerIndex(e){if(settings.source==='pointer'&&e.pointerType!=='touch'&&e.target.closest('#stage')&&!e.target.closest('.stage-tools,.pause-cover,input,select,[data-switch]'))return settings.pointer.indexOf(e.button);if(e.target.id==='game-canvas'&&game?.item.type==='ce'&&(e.button===0||e.pointerType==='touch'))return 0;const b=e.target.closest('[data-switch],[data-test]');if(b)return +(b.dataset.switch??b.dataset.test);if(settings.source==='pointer'&&(e.target.id==='game-canvas'||$('#test-log')||page==='home'&&homeScan))return settings.pointer.indexOf(e.button);return -1;}
document.addEventListener('pointerdown',e=>{keyboardNavigation=false;const i=pointerIndex(e);if(i<0)return;lastPointerTime=performance.now();const captureChoice=settings.source==='pointer'&&e.pointerType!=='touch'&&!!e.target.closest('[data-choice]');if(e.target.closest('input,select')||e.target.closest('button')&&!e.target.closest('[data-switch],[data-test]')&&!captureChoice)return;e.preventDefault();audioStart();const token='pointer-'+e.pointerId;activePointers.set(e.pointerId,{i,token,captureChoice});if(captureChoice)capturedChoiceClickUntil=performance.now()+1000;engine.down(i,token);// the press may have redrawn the overlay and taken the button away (the switch hint, a zone): then there is nothing to capture
 if(e.target.isConnected)try{e.target.setPointerCapture?.(e.pointerId);}catch{}});
function pointerUp(e){lastPointerTime=performance.now();const a=activePointers.get(e.pointerId);if(a){if(a.captureChoice)capturedChoiceClickUntil=performance.now()+500;engine.up(a.i,a.token);activePointers.delete(e.pointerId);}}
document.addEventListener('pointerup',pointerUp);document.addEventListener('pointercancel',pointerUp);
document.addEventListener('click',e=>{if(settings.source!=='pointer'||performance.now()-lastPointerTime<500)return;if(e.target.id!=='game-canvas'&&!e.target.closest('.test-zone'))return;const i=settings.pointer.indexOf(e.button);if(i>=0)engine.pulse(i,'click-only');});
document.addEventListener('contextmenu',e=>{if(settings.source==='pointer'&&(e.target.closest('#stage')||$('#test-log')))e.preventDefault();});
document.addEventListener('keydown',e=>{if(e.code==='Tab')keyboardNavigation=true;if(keyboardNavigation&&['Space','Enter'].includes(e.code)&&e.target.closest('button,a')&&!e.target.closest('[data-switch],[data-test]')&&learn===null)return;if(learn!==null){e.preventDefault();if(e.code==='Escape'){learn=null;drawSettings();return;}const keys=[...settings.keys];keys[learn]=e.code;if(changeSetting('keys',keys)){learn=null;drawSettings();}return;}
 if(e.code==='Escape'&&page==='game'&&!$('dialog[open]')){e.preventDefault();home();return;}if(settings.source!=='keyboard'||e.ctrlKey||e.metaKey||e.altKey)return;
 if(e.target.closest('input,select,textarea')||e.target.isContentEditable)return;if($('dialog[open]')&&!$('#test-log'))return;
 const i=settings.keys.indexOf(e.code);if(i<0)return;e.preventDefault();if(e.repeat)return;audioStart();engine.down(i,'key-'+e.code);});
document.addEventListener('keyup',e=>{const i=settings.keys.indexOf(e.code);if(i>=0)engine.up(i,'key-'+e.code);});
window.addEventListener('pagehide',()=>{if(page==='game')logEnd();});
window.addEventListener('blur',()=>{engine.cancel();if(page==='game')pauseGame();engine.cancel();stopSound();});
window.addEventListener('focus',()=>{lastTime=performance.now();engine.resume();scan.elapsed=0;});
document.addEventListener('visibilitychange',()=>{if(document.hidden){engine.cancel();if(page==='game')pauseGame();engine.cancel();stopSound();}else {lastTime=performance.now();engine.resume();scan.elapsed=0;}});
window.addEventListener('gamepaddisconnected',()=>{engine.cancel();engine.releaseAll();if(page==='game')pauseGame('Comandament desconnectat. Reconnecta’l abans de continuar.');engine.resume();});
window.addEventListener('resize',()=>{if(page==='home')paintPreviews()});
const gamepadLast=new Map();
